{
  "name": "三路可编程直流电源",
  "name_en": "Triple-Output Programmable DC Power Supply",
  "manufacturer": "Agilent Technologies",
  "description": "E3631A 是一台台式三路可编程直流电源，可为实验电路、电子模块和原型系统提供稳定的直流电压与电流输出。它支持多通道输出、输出开关、远端感测以及电压、电流、功率测量，常用于电子测试、器件供电和实验室台架搭建。",
  "description_en": "The E3631A is a benchtop triple-output programmable DC power supply used to provide stable DC voltage and current to circuits, electronic modules, and prototype systems. It supports multiple output channels, output enable control, remote sensing, and voltage, current, and power measurements, making it suitable for electronics testing, device powering, and general laboratory bench work.",
  "tag_hints": [
    "DC power supply",
    "triple output",
    "programmable PSU",
    "bench electronics testing",
    "remote sensing",
    "voltage and current sourcing",
    "output measurement"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电源，并默认选择 2 号输出通道。",
      "description_en": "Initialize the power supply and select output channel 2 by default."
    },
    {
      "action_name": "auto-lock_front_panel",
      "description": "锁定或解锁前面板按键与本地操作。",
      "description_en": "Lock or unlock the front-panel controls and local operation."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量当前所选输出通道的输出电流。",
      "description_en": "Measure the output current of the currently selected channel."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量当前所选输出通道的输出功率。",
      "description_en": "Measure the output power of the currently selected channel."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量当前所选输出通道的输出电压。",
      "description_en": "Measure the output voltage of the currently selected channel."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "启用或关闭远端感测，以补偿连接导线上的压降。",
      "description_en": "Enable or disable remote sensing to compensate for voltage drop in the output leads."
    },
    {
      "action_name": "auto-select_channel",
      "description": "选择要操作或测量的输出通道。",
      "description_en": "Select the output channel to control or measure."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置当前所选输出通道的电流设定值。",
      "description_en": "Set the current setpoint for the currently selected output channel."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置当前所选输出通道的电压设定值。",
      "description_en": "Set the voltage setpoint for the currently selected output channel."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭电源输出。",
      "description_en": "Turn the power supply output on or off."
    }
  ]
}

